package interium.mixin;
import net.minecraft.client.network.ClientPlayerInteractionManager;import net.minecraft.client.MinecraftClient;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.entity.Entity;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(ClientPlayerInteractionManager.class) public abstract class InteriumAttackHooks {@Inject(method="attackEntity",at=@At("TAIL"))private void interium$hit(PlayerEntity p,Entity e,CallbackInfo ci){interium.fabric.InteriumMovementHooks.attacked(MinecraftClient.getInstance());}}
